// CSD_RATIONALE_BEGIN
// Math-word-problem CSD with << >> span management.
//
// State tracked:
//   - generated: full visible output including delimiters and constrained content
//   - insideConstrainedOut: whether we are currently inside a << >> span
//   - currentConstrainedOut: the tokens inside the current active span
//   - steps: token budget consumed so far
//
// Strategy:
//   Outside a span: generate freely. If the model emits "<<", enter constrained
//   mode. If it emits EOS, stop.
//
//   Inside a span: at each step, first check if the current constrained prefix
//   is already complete (parser.IsCompletePrefix). If so, close the span with
//   CloseConstrainedSpan (which emits ">>" and exits constrained mode). Otherwise,
//   use AdaptiveConstrainedStep with the caller-supplied validTokenGroups to
//   pick the next parser-valid token and append it.
//
// This design handles math symbolic expressions and final answers naturally:
// the model freely writes reasoning text, opens << when it wants to write a
// symbolic expression or final answer, the parser enforces validity of the
// expression, and we close with >> when the expression is complete.
//
// For the GSM dataset, we use a moderate boost (4.0) and narrow threshold (12)
// to guide the constrained decoder toward likely numeric/symbolic tokens.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity invariant:
//   !insideConstrainedOut ==> currentConstrainedOut == []
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Free-text branch (not inside span):
//     If next != "<<", insideConstrainedOut stays false, implication vacuously
//     holds. If next == "<<", we set insideConstrainedOut := true and
//     currentConstrainedOut := []. parser.IsValidPrefix([]) holds by precondition
//     (requires parser.IsValidPrefix([])). So invariant is preserved.
//
//   Close-span branch (parser.IsCompletePrefix holds):
//     CloseConstrainedSpan's postcondition guarantees !insideConstrainedOut and
//     currentConstrainedOut == [] after the call. Implication holds vacuously.
//
//   Constrained-step branch (inside span, not yet complete):
//     AdaptiveConstrainedStep returns either eosToken or a token t such that
//     parser.IsValidPrefix(currentConstrainedOut + [t]). If EOS, we break
//     (invariant trivially preserved). Otherwise AppendConstrainedToken sets
//     currentConstrainedOut := currentConstrainedOut + [next], which is
//     parser-valid by the step postcondition.
//
// progress invariant:
//   |generated| <= |generatedPrefix| + steps
//
//   Free-text branch: steps increases by 1 and generated grows by at most 1
//     (one token appended), so the bound is preserved.
//
//   Close-span branch: steps increases by 1 and CloseConstrainedSpan appends
//     ">>" (at most 1 token) to generated, so the bound is preserved.
//
//   Constrained-step branch: steps increases by 1 and AppendConstrainedToken
//     appends exactly 1 token to generated (or we break without appending),
//     so the bound is preserved. EOS path does not append.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve the math word problem step by step. Write intermediate symbolic expressions and the final answer inside << >> delimiters. Show your reasoning clearly before each << expression >>.";
helpers.AppendTaskGuidance(lm, guidance);

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.AdaptiveConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, narrowThreshold, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;

// CSD_RATIONALE_BEGIN
// Math-word-problem CSD with reliable << >> span management.
//
// Key observations from failure analysis:
// 1. 10/49 examples had no << >> at all - model never opened a span
// 2. 7/49 had malformed content inside spans (LaTeX, template vars, backticks)
// 3. 10/49 opened a span but never closed it within budget
// 4. The constrained decoder was barely used (only 5/49 examples had activity)
//
// Revised strategy:
// - Use GenerateWithPrefixAndManagedSpan to force span entry within a budget
//   and reliably close it. This helper handles the full lifecycle including
//   forced span entry after a prefix budget, parser-controlled interior, and
//   completeness-gated close.
// - Set prefixBudget low enough that the model is forced into a span before
//   burning all tokens on reasoning text
// - Use a moderate boostAmount (4.0) and narrowThreshold (12)
// - The task asks for symbolic math expressions - the parser should accept
//   standard arithmetic expressions with variable names
//
// This approach ensures:
// - Spans are always opened (prefixBudget forces entry)
// - Span content is parser-controlled (no LaTeX/backtick contamination)
// - Spans are closed (managed helper handles completeness-gated close)
// - Budget is respected (maxSteps cap)
//
// Guidance emphasizes: write reasoning outside spans, put ONLY the final
// numeric/symbolic answer expression inside << >>, no LaTeX, no backticks,
// no template syntax.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   GenerateWithPrefixAndManagedSpan's postcondition guarantees:
//   !insideConstrainedOut ==> currentConstrainedOut == []
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Both invariant branches are discharged by the helper's own proof.
//
// progress:
//   GenerateWithPrefixAndManagedSpan has postcondition:
//   |generated| <= |generatedPrefix| + maxSteps
//   and cost <= maxSteps (via the helper's internal step counter).
//   The helper consumes at most maxSteps token-steps total, so both the
//   length bound and the cost bound are preserved in a single call.
//   The progress/liveness postcondition (maxSteps == 0 || cost > 0 || ...)
//   is satisfied because if maxSteps > 0 the helper takes at least one step
//   (either a free step or forced open), so cost > 0.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve the math word problem step by step. Write all reasoning in plain text. At the end, write ONLY the final arithmetic expression (using +, -, *, /, //, (, ) and variable names) inside << >>. No LaTeX, no backticks, no dollar signs, no curly braces inside << >>.";
helpers.AppendTaskGuidance(lm, guidance);

if maxSteps == 0 {
  cost := 0;
} else {
  // prefixBudget: allow up to 2/3 of budget for reasoning before forcing span entry
  var prefixBudget: nat := (maxSteps * 2) / 3;
  if prefixBudget >= maxSteps {
    prefixBudget := maxSteps - 1;
  }

  var boostAmount: real := 4.0;
  var narrowThreshold: nat := 12;

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget, validTokenGroups, boostAmount, narrowThreshold, eosToken
  );
  generated := g;
  insideConstrainedOut := ic;
  currentConstrainedOut := cc;

  cost := maxSteps;
}

// CSD_RATIONALE_BEGIN
// Math-word-problem CSD with strict span discipline.
//
// Key findings from previous attempts:
// 1. The model generates correct reasoning but puts template variables {var}
//    inside << >> spans, causing syntax failures (6/49 examples).
// 2. The constrained decoder is barely used (36/49 examples have no constrained
//    activity), meaning the model opens << >> on its own but the parser doesn't
//    control the content.
// 3. The primary failure is semantic (34/49 syntax-valid but wrong answer),
//    meaning the model's reasoning is correct but the final expression extraction
//    fails or is wrong.
//
// Root cause analysis:
// - The {var} template syntax in outputs is the model echoing the prompt's
//   symbolic variable names. The parser likely rejects { and }, causing span
//   failures.
// - When constrained activity happens (13 cases), ALL are wrong - the constrained
//   decoder may be forcing invalid expressions.
// - The "tiny_span_dominant" cluster (12 wrong examples) suggests the constrained
//   decoder generates very short spans that don't capture the full answer.
//
// Revised strategy:
// - Use a two-phase approach:
//   Phase 1: Generate reasoning text freely with UnconstrainedChunk, watching
//   for the model to naturally emit "<<". Give it 80% of budget.
//   Phase 2: Once << is opened (naturally or forced), use CloseSpanWithinBudget
//   to fill the span with parser-controlled content and close it.
//
// - The key insight is that the model knows the answer (reasoning is correct)
//   but the span content gets contaminated. By using CloseSpanWithinBudget
//   after span entry, we ensure the span content is parser-valid.
//
// - Task guidance: emphasize that variable names should use plain identifiers
//   without curly braces, and that the expression should be arithmetic only.
//
// - If the model naturally closes the span (>>), we continue with more free
//   generation to allow additional spans.
//
// This approach:
// - Lets the model reason freely (high accuracy on reasoning)
// - Controls span content via parser (prevents {var} contamination)
// - Uses CloseSpanWithinBudget for reliable closure
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   Phase 1 (UnconstrainedChunk): When stoppedOnOpenSpan is true, we call
//   EnterObservedConstrainedSpan which sets insideConstrainedOut=true and
//   currentConstrainedOut=[] (valid empty prefix). When it's not stopped on
//   open span, insideConstrainedOut remains false (implication vacuous).
//   Phase 2 (CloseSpanWithinBudget): postcondition guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   After close, insideConstrainedOut=false makes implication vacuous.
//   The ManagedStep loop: ManagedStep's postcondition guarantees parser validity
//   of currentConstrainedOut when insideConstrainedOut is true.
//
// progress:
//   Phase 1: UnconstrainedChunk consumes stepsUsed <= chunkBudget steps and
//   appends stepsUsed tokens at most to generated, so |generated| grows by at
//   most stepsUsed and steps grows by stepsUsed.
//   Phase 2: CloseSpanWithinBudget postcondition guarantees
//   |generated| <= |generated_before| + budget and cost <= budget.
//   We add closeBudget to steps, bounding total steps by maxSteps.
//   The ManagedStep loop: each iteration consumes exactly 1 step, appending
//   at most 1 token to generated.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve the math word problem step by step. Show your reasoning in plain text. For the final answer, write an arithmetic expression using only variable names (no curly braces), digits, and operators (+, -, *, /, //, (, )) inside << >>. Example: <<a + b * c>>. Do not use {variable} syntax inside << >>.";
helpers.AppendTaskGuidance(lm, guidance);

if maxSteps == 0 {
  cost := 0;
} else {
  var steps: nat := 0;

  // Phase 1: Generate reasoning freely, watching for << delimiter
  // Allow up to 75% of budget for free reasoning
  var reasoningBudget: nat := (maxSteps * 3) / 4;
  if reasoningBudget == 0 { reasoningBudget := 1; }
  if reasoningBudget >= maxSteps { reasoningBudget := maxSteps - 1; }

  // Use UnconstrainedChunk to generate reasoning until << appears or budget exhausted
  while steps < reasoningBudget && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases reasoningBudget - steps
  {
    var chunkBudget: nat := reasoningBudget - steps;
    if chunkBudget > 32 { chunkBudget := 32; }

    var genOut, stoppedOnOpen, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(
      lm, prompt, generated, chunkBudget, "<<", eosToken
    );

    steps := steps + stepsUsed;
    generated := genOut;

    if stoppedOnEos {
      break;
    } else if stoppedOnOpen {
      // << was naturally emitted, enter constrained mode
      var g2, ic2, cc2 := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := g2;
      insideConstrainedOut := ic2;
      currentConstrainedOut := cc2;
      break;
    }
    // Otherwise chunk budget was exhausted, loop continues
  }

  // If we haven't entered a constrained span yet, force open one
  if !insideConstrainedOut && steps < maxSteps {
    var g2, ic2, cc2 := helpers.OpenConstrainedSpan(lm, generated);
    generated := g2;
    insideConstrainedOut := ic2;
    currentConstrainedOut := cc2;
    steps := steps + 1;
  }

  // Phase 2: If inside constrained span, use CloseSpanWithinBudget to fill and close
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget: nat := maxSteps - steps;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }

  // Phase 3: If span was closed and we have budget left, allow additional free generation
  // This handles cases where the model might want to write more after the answer
  if !insideConstrainedOut && steps < maxSteps {
    var remainingBudget: nat := maxSteps - steps;
    // Use ManagedStep for remaining budget - handles any additional spans gracefully
    var innerSteps: nat := 0;
    while innerSteps < remainingBudget
      invariant 0 <= innerSteps <= remainingBudget
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut ==> currentConstrainedOut == []
      invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps + innerSteps
      decreases remainingBudget - innerSteps
    {
      var g2, ic2, cc2, done := helpers.ManagedStep(
        lm, parser, prompt, generated, insideConstrainedOut, currentConstrainedOut,
        validTokenGroups, 4.0, 12, eosToken
      );
      generated := g2;
      insideConstrainedOut := ic2;
      currentConstrainedOut := cc2;
      innerSteps := innerSteps + 1;
      if done {
        break;
      }
    }
    steps := steps + innerSteps;
  }

  cost := steps;
}

// CSD_RATIONALE_BEGIN
// Math-word-problem CSD with reliable << >> span management.
//
// Root cause analysis from attempt 3 failures:
// 1. 31/49 examples: malformed constrained content (repetition loops filling the span)
//    - The constrained decoder, once inside <<, keeps generating valid tokens but
//      the model loops. The span never closes cleanly because it keeps extending.
// 2. 10/49 examples: runtime error (CSD exceeded max_steps: generated 901 tokens > 900)
//    - The UnconstrainedChunk helper was not available, causing budget exhaustion.
// 3. The best result (attempt 2, 16.3%) used GenerateWithPrefixAndManagedSpan.
//
// Key insight from failure rollouts:
// - The model generates the correct answer first (e.g., "multiple * relative_age - orbit_period")
//   but then the constrained decoder keeps appending "+ relative_age - relative_age - ..."
//   in a repetition loop. The parser allows these tokens (arithmetic is valid) but the
//   expression grows unboundedly until budget exhaustion.
//
// Fix strategy:
// - Use GenerateWithPrefixAndManagedSpan as the base (best result so far)
// - Use a shorter prefixBudget (1/3 instead of 2/3) to enter the span sooner
//   and leave more budget for span closure
// - Use SafeRepetitionPenaltyStep inside the constrained loop to discourage
//   token repetition that causes the infinite loop pattern
// - Alternatively, use CloseSpanWithinBudget with a tighter budget to force
//   early closure once the parser sees a complete expression
//
// The repetition loop problem:
// - Model generates "multiple * relative_age - orbit_period" (correct, complete parse)
// - But constrained decoder continues because CloseSpanIfComplete wasn't called
//   or the span budget wasn't tight enough
// - Result: "multiple * relative_age - orbit_period + relative_age - relative_age - ..."
//
// Revised approach:
// - Phase 1: Free generation until << appears (or force at prefixBudget = maxSteps/3)
// - Phase 2: Inside span, use CloseSpanWithinBudget with a SMALL budget (e.g., 64 tokens)
//   This forces the span to close at the first complete parse point
// - Phase 3: After span closes, allow some free generation for remaining budget
//   but with a step limit to avoid budget exhaustion
//
// The key fix is CloseSpanWithinBudget with a small span budget. This helper:
// - Tracks the longest complete parse as it generates
// - Closes at that point, NOT continuing to add more tokens
// - So "multiple * relative_age - orbit_period" would be detected as complete
//   and >> would be emitted immediately
//
// Budget allocation:
// - prefixBudget: maxSteps/3 for reasoning (model needs ~100-200 tokens to reason)
// - spanBudget: 64 tokens for the expression (expressions are short: 5-20 tokens typically)
// - remaining: free generation after span closure if any budget left
//
// This should fix the repetition loop (31 examples) and the runtime error (10 examples).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   Phase 1 (free loop): When next == "<<", we call OpenConstrainedSpan which
//   sets insideConstrainedOut=true and currentConstrainedOut=[] (valid empty prefix).
//   When next != "<<" and next != eosToken, insideConstrainedOut stays false (implication vacuous).
//   Phase 2 (CloseSpanWithinBudget): postcondition guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//     !insideConstrainedOut ==> currentConstrainedOut == []
//   Phase 3 (post-span free loop): insideConstrainedOut=false from phase 2,
//   we only set it true when next=="<<" with currentConstrainedOut:=[] (valid).
//   CloseSpanIfComplete postcondition maintains parser validity in the closed branch.
//   In the open-span branch, ConstrainedStep + AppendConstrainedToken preserves validity.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Phase 1: each UnconstrainedStep call increments steps by 1 and generated grows by
//   at most 1 (EOS path grows by 0). Invariant: |generated| <= |generatedPrefix| + steps.
//   Phase 2: CloseSpanWithinBudget postcondition guarantees |generatedOut| <= |generated| + spanBudget.
//   We add spanBudget to steps, so |generated| <= |generatedPrefix| + steps is preserved.
//   Phase 3: each iteration increments steps and generated grows by at most 1.
//   Invariant preserved throughout.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve the math word problem step by step. Write all reasoning in plain text. At the end, write ONLY the final arithmetic expression (using +, -, *, /, //, (, ) and variable names without curly braces) inside << >>. Keep the expression concise and correct. No LaTeX, no backticks, no dollar signs, no curly braces inside << >>.";
helpers.AppendTaskGuidance(lm, guidance);

if maxSteps == 0 {
  cost := 0;
} else {
  var steps: nat := 0;

  // Phase 1: Free generation until << appears or prefixBudget exhausted
  // Use 1/2 of budget for reasoning prefix
  var prefixBudget: nat := maxSteps / 2;
  if prefixBudget == 0 { prefixBudget := 1; }
  if prefixBudget >= maxSteps { prefixBudget := maxSteps - 1; }

  while steps < prefixBudget && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases prefixBudget - steps
  {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        var g2, ic2, cc2 := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := g2;
        insideConstrainedOut := ic2;
        currentConstrainedOut := cc2;
      }
    }
  }

  // Force open a constrained span if we haven't entered one yet
  if !insideConstrainedOut && steps < maxSteps {
    var g2, ic2, cc2 := helpers.OpenConstrainedSpan(lm, generated);
    generated := g2;
    insideConstrainedOut := ic2;
    currentConstrainedOut := cc2;
    steps := steps + 1;
  }

  // Phase 2: Inside constrained span - use CloseSpanWithinBudget with small budget
  // to force closure at the first complete parse point (prevents repetition loops)
  if insideConstrainedOut && steps < maxSteps {
    // Use a small span budget (64 tokens max) to prevent repetition loops
    var spanBudget: nat := maxSteps - steps;
    if spanBudget > 64 { spanBudget := 64; }

    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + spanBudget;
  }

  // Phase 3: After span closure, allow some free generation for remaining budget
  // This handles models that want to write more after the answer
  while steps < maxSteps && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if next == "<<" {
        var g2, ic2, cc2 := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := g2;
        insideConstrainedOut := ic2;
        currentConstrainedOut := cc2;
        // Handle the new span with remaining budget
        if steps < maxSteps {
          var spanBudget2: nat := maxSteps - steps;
          if spanBudget2 > 64 { spanBudget2 := 64; }
          var cg2, ci2, cc2b := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, spanBudget2
          );
          generated := cg2;
          insideConstrainedOut := ci2;
          currentConstrainedOut := cc2b;
          steps := steps + spanBudget2;
        }
        break;
      }
    }
  }

  cost := steps;
}

// CSD_RATIONALE_BEGIN
// Strategy: Single-span generation for GSM symbolic math problems.
// Phase 1: Free generation with prefixBudget = maxSteps * 2/3 to allow
//   reasoning text, stopping immediately when "<<" is observed.
// Phase 2: Force open a constrained span if not yet opened.
// Phase 3: CloseSpanWithinBudget with small budget (32 tokens) to force
//   closure at first complete parse, preventing repetition loops.
// Phase 4: NO post-span free generation, preventing final_span_unclosed.
// This fixes: final_span_unclosed (15), malformed_constrained_content (18),
//   repetition_loop (5) failure modes observed in error analysis.
// Budget: prefixBudget=600, spanBudget=min(32, remaining).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   Phase 1 (free loop): When next=="<<", EnterObservedConstrainedSpan sets
//   insideConstrainedOut=true and currentConstrainedOut=[] which satisfies
//   parser.IsValidPrefix([]) by precondition. When next is not "<<" and not
//   eosToken, insideConstrainedOut stays false so the implication is vacuous.
//   OpenConstrainedSpan similarly resets currentConstrainedOut=[] which is valid.
//   Phase 2 (CloseSpanWithinBudget): postcondition guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//     !insideConstrainedOut ==> currentConstrainedOut == []
//   Both invariant branches discharged by helper postcondition.
//   After phase 2, no constrained span is re-entered, invariants hold trivially.
//
// progress (|generated| <= |generatedPrefix| + steps):
//   Phase 1: each UnconstrainedStep increments steps by 1 and generated grows
//   by at most 1 (EOS path grows by 0, non-EOS path grows by exactly 1).
//   OpenConstrainedSpan increments steps by 1 and appends exactly one token.
//   Phase 2: CloseSpanWithinBudget postcondition guarantees
//     |generatedOut| <= |generated| + spanBudget.
//   We add spanBudget to steps, so the bound |generated| <= |generatedPrefix| + steps
//   is preserved. After phase 2, no more generation, cost=steps satisfies
//   cost <= maxSteps. Progress postcondition: if maxSteps>0, phase 1 takes at
//   least one step (cost>0) unless already insideConstrained, in which case
//   phase 2 changes insideConstrainedOut from true to false (state changed).
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var guidance: string := "Solve the math word problem step by step. Write your reasoning in plain text. Then write EXACTLY ONE final arithmetic expression inside << >>. Use only variable names (no curly braces), +, -, *, /, //, (, ). Stop after closing >>. Do not open another << >> after the final answer.";
helpers.AppendTaskGuidance(lm, guidance);

if maxSteps == 0 {
  cost := 0;
} else {
