  var prefixBudget: nat := (maxSteps * 72) / 100;
  if prefixBudget >= maxSteps {
    prefixBudget := maxSteps - 1;
  }

  var steps: nat := 0;

  // Phase 1: Free reasoning generation
  while steps < prefixBudget && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases prefixBudget - steps
  {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else if next == "<<" {
      generated := generated + [next];
      var g2, ic2, cc2 := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := g2;
      insideConstrainedOut := ic2;
      currentConstrainedOut := cc2;
    } else {
      generated := generated + [next];
    }
  }

  // Phase 2: Force open constrained span if not already inside one
  if !insideConstrainedOut && steps < maxSteps {
    var g2, ic2, cc2 := helpers.OpenConstrainedSpan(lm, generated);
    generated := g2;
    insideConstrainedOut := ic2;
    currentConstrainedOut := cc2;
    steps := steps + 1;
  }

  // Phase 3: Constrained span loop with temperature-based anti-repetition
  // Use SafeTemperatureConstrainedStep with temperature > 1.0 to prevent repetition loops
  while insideConstrainedOut && steps + 2 <= maxSteps
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    // Try to close if complete (costs 1 step)
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
    } else {
      // Generate next constrained token with temperature scaling to prevent repetition
      // temperature > 1.0 flattens logits, reducing chance of one token dominating
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeTemperatureConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, 1.5, eosToken);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var g3, ic3, cc3 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := g3;
        insideConstrainedOut := ic3;
        currentConstrainedOut := cc3;
      }
    }
  }

  // Phase 4: Use CloseSpanWithinBudget as fallback to guarantee closure
  if insideConstrainedOut && steps < maxSteps {
    var closeBudget: nat := maxSteps - steps;
    var g4, ic4, cc4 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := g4;
    insideConstrainedOut := ic4;
    currentConstrainedOut := cc4;
    steps := maxSteps;
  }

  cost := steps;
}

